def build_controller():
    return {
        "name": "det_bbmi_adaptive_portfolio_v3",
        "description": "Deterministic instance-adaptive hyper-heuristic over frozen portfolio with bounded stagnation/candidate/restart/annealing adjustments; interpretable structure-driven selection with diversity-failure safeguards.",
        "default_heuristic": "farthest_insertion_two_opt",
        "random_like_heuristic": "annealed_multi_start",
        "clustered_heuristic": "cluster_first_local_search",
        "grid_like_heuristic": "candidate_pruned_two_opt",
        "two_cluster_bottleneck_heuristic": "edge_preserving_restart",
        "corridor_heuristic": "limited_three_opt",
        "nearest_neighbor_trap_heuristic": "nearest_neighbor_multistart",
        "stagnation_switch_heuristic": "farthest_insertion_two_opt",
        "stagnation_threshold": 5,
        "low_improvement_threshold": 0.12,
        "failed_perturbation_threshold": 3,
        "time_budget_trigger": 0.68,
        "candidate_limit_offset": 1,
        "restart_offset": 2,
        "temperature_scale": 1.25,
        "acceptance_bias": 0.009,
        "policy": {
            "base_selection": [
                {
                    "when": [
                        "features.get('bottleneck_score',0.0) >= 0.6",
                        "features.get('two_cluster_bottleneck_score',0.0) >= 0.4"
                    ],
                    "then": "two_cluster_bottleneck_heuristic"
                },
                {
                    "when": [
                        "features.get('clusteredness_score',0.0) >= 0.52",
                        "features.get('grid_likeness',0.0) <= 0.3"
                    ],
                    "then": "clustered_heuristic"
                },
                {
                    "when": [
                        "features.get('grid_likeness',0.0) >= 0.42",
                        "features.get('convex_hull_ratio',0.0) >= 0.84"
                    ],
                    "then": "grid_like_heuristic"
                },
                {
                    "when": [
                        "features.get('corridor_score',0.0) >= 0.45",
                        "features.get('coordinate_spread_norm',0.0) <= 0.4"
                    ],
                    "then": "corridor_heuristic"
                },
                {
                    "when": [
                        "features.get('nearest_neighbor_trap_score',0.0) >= 0.3",
                        "features.get('nn_distance_cv',0.0) >= 0.45"
                    ],
                    "then": "nearest_neighbor_trap_heuristic"
                }
            ],
            "diversity_failure_mode": {
                "when": [
                    "context.get('replay_mode','') == 'diversity_failure'",
                    "context.get('failure_archive_size',0) >= 6"
                ],
                "then": {
                    "selection_restriction": [
                        "default_heuristic",
                        "grid_like_heuristic",
                        "two_cluster_bottleneck_heuristic"
                    ],
                    "prefer_generalists_over_specialists": True
                }
            },
            "tie_break": {
                "deterministic_order": [
                    "default_heuristic",
                    "grid_like_heuristic",
                    "two_cluster_bottleneck_heuristic",
                    "clustered_heuristic",
                    "corridor_heuristic",
                    "nearest_neighbor_trap_heuristic"
                ]
            },
            "fallback": "default_heuristic"
        },
        "schedule": {
            "stagnation_rule": {
                "trigger_condition": [
                    "online.get('stagnation_length',0) >= stagnation_threshold",
                    "online.get('recent_improvement_rate',0.0) <= low_improvement_threshold"
                ],
                "switch_to": "stagnation_switch_heuristic",
                "perturbation_escalation": {
                    "if_failed_perturbations": [
                        "online.get('failed_perturbation_count',0) >= failed_perturbation_threshold"
                    ],
                    "then": {
                        "use_random_like_phase": True,
                        "random_like_heuristic": "random_like_heuristic"
                    }
                },
                "edge_skew_sensitive_bias": {
                    "if_conditions": ["online.get('edge_length_skew_in_current_tour',0.0) >= 0.65"],
                    "then": {
                        "prefer_two_opt_stability": True,
                        "avoid_random_like_thrashing": True
                    }
                }
            },
            "time_rule": {
                "trigger_condition": ["online.get('time_budget_used',0.0) >= time_budget_trigger"],
                "then": {
                    "final_refinement_bias": True,
                    "candidate_limit_offset": "candidate_limit_offset",
                    "restart_offset": "restart_offset",
                    "annealing_adjustment": {
                        "temperature_scale": "temperature_scale",
                        "acceptance_bias": "acceptance_bias"
                    }
                }
            }
        },
        "determinism": {
            "seed_strategy": "deterministic_hash_from_instance_name_and_dimension",
            "ties": "lexicographic_on_heuristic_roles",
            "selection_is_pure_function_of_features": True
        }
    }

